import{ListenWatch}from"../primitives/ListenWatch.js";class Props extends ListenWatch{constructor(){super(),this.name=this.id||this.nodeName.toLowerCase(),this.defaultTo=()=>[this]}handle(event){let data=event.detail;if(!data)return;this.fromElems.indexOf(event.target);for(const[i,to]of this.toElems.entries())Object.keys(data).forEach((k,i)=>{to.style.setProperty(`--${this.name}-${k}`,data[k])})}handleWatch(list,observer){if(!this.bypass)for(const[i,to]of this.toElems.entries())for(const r of list){this.fromElems.indexOf(r.target);to.style.setProperty(`--${this.name}-${r.attributeName}`,r.target[r.attributeName])}}}export{Props};